Translate the following Java 8 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String totalLines = sc.nextLine();
        String data = sc.nextLine();

        int maxLen = 0;
        int tokenCount = 0;
        int currentIndex = 0;
        int lastIndex = 0;

        while (currentIndex < data.lastIndexOf(')')) {
            int openParen = data.indexOf('(', currentIndex);
            int closeParen = data.indexOf(')', openParen);
            String segment = data.substring(lastIndex, openParen);
            StringTokenizer st = new StringTokenizer(segment, "_");
            while (st.hasMoreTokens()) {
                int len = st.nextToken().length();
                if (len > maxLen) maxLen = len;
            }
            String inside = data.substring(openParen + 1, closeParen);
            StringTokenizer innerSt = new StringTokenizer(inside, "_");
            while (innerSt.hasMoreTokens()) {
                String token = innerSt.nextToken();
                if (!token.equals("")) tokenCount++;
            }
            lastIndex = closeParen + 1;
            currentIndex = closeParen;
        }

        String tail = data.substring(lastIndex);
        StringTokenizer tailSt = new StringTokenizer(tail, "_");
        while (tailSt.hasMoreTokens()) {
            int len = tailSt.nextToken().length();
            if (len > maxLen) maxLen = len;
        }

        System.out.println(maxLen + " " + tokenCount);
    }
}
